-- ============================================================
-- 027_ielts_vocabulary_words_600_799.sql
-- Content batch: IELTS Band 8 vocabulary words 600-799,
-- transcribed from "1000 Essential Words for Band 8" (word, part of
-- speech, definition, and example extracted from the source; Bangla
-- meanings authored fresh, since the PDF's own Bangla text layer is
-- corrupted at the font level -- see migration notes).
-- ============================================================

do $$
declare
  v_opinion_and_stance uuid;
  v_hedging_and_nuance uuid;
  v_agreement_and_disagreement uuid;
  v_comparison_and_contrast uuid;
  v_cause_and_effect uuid;
  v_linking_and_discourse_markers uuid;
  v_idiomatic_spoken_expressions uuid;
begin
  select cn.id into v_opinion_and_stance from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'opinion-and-stance';
  select cn.id into v_hedging_and_nuance from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'hedging-and-nuance';
  select cn.id into v_agreement_and_disagreement from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'agreement-and-disagreement';
  select cn.id into v_comparison_and_contrast from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'comparison-and-contrast';
  select cn.id into v_cause_and_effect from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'cause-and-effect';
  select cn.id into v_linking_and_discourse_markers from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'linking-and-discourse-markers';
  select cn.id into v_idiomatic_spoken_expressions from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'idiomatic-spoken-expressions';

end $$;
